#include <cstdio>
#include <algorithm>
#include <vector>
using namespace std;

int n, sum;
int a[1005], b[1005];
vector<pair<int, int>> events;

bool check(int x) {
    int now = x, cnt = 0, day = 0;

    for (int i = 1; i <= n; ++i)
        b[i] = a[i];

    size_t p = 0;
    while (p < events.size() && events[p].first > x)
        ++p;

    for (int i = x; i >= 1; --i) {
        while (p < events.size() && events[p].first == i) {
            int item = events[p].second;
            int used = min(now, b[item]);
            cnt += used;
            now -= used;
            b[item] -= used;
            ++p;
        }

        if (now >= i) {
            --now;
            ++day;
        }
    }

    return sum - cnt <= day / 2;
}

int main() {
    int m, ans = 0;
    scanf("%d %d", &n, &m);

    for (int i = 1; i <= n; ++i) {
        scanf("%d", &a[i]);
        sum += a[i];
    }

    events.reserve(m);
    for (int i = 0; i < m; ++i) {
        int d, item;
        scanf("%d %d", &d, &item);
        events.emplace_back(d, item);
    }

    sort(events.begin(), events.end(),
         [](const pair<int, int>& x, const pair<int, int>& y) {
             if (x.first != y.first) return x.first > y.first;
             return x.second < y.second;
         });

    events.erase(unique(events.begin(), events.end()), events.end());

    if (sum != 0) {
        int l = 1, r = sum * 2;
        while (l <= r) {
            int mid = l + (r - l) / 2;
