}

#include <cstdio>
#include <algorithm>
#include <vector>
using namespace std;

struct Node {
    int d, b;

    bool operator<(const Node& other) const {
        if (d != other.d) return d < other.d;
        return b < other.b;
    }

    bool operator==(const Node& other) const {
        return d == other.d && b == other.b;
    }
};

int n, sum;
int a[1005], remaining[1005];
vector<Node> events;

bool check(int x) {
    int now = x, cnt = 0, days = 0;

    for (int i = 1; i <= n; ++i)
        remaining[i] = a[i];

    int pos = upper_bound(
        events.begin(), events.end(), Node{x, n + 1}
    ) - events.begin();

    for (int day = x; day >= 1; --day) {
        int end = pos;
        while (pos > 0 && events[pos - 1].d == day)
            --pos;

        for (int i = pos; i < end; ++i) {
            int item = events[i].b;
            int used = min(now, remaining[item]);
            cnt += used;
            now -= used;
            remaining[item] -= used;
        }

        if (now >= day) {
            --now;
            ++days;
        }
    }

    return sum - cnt <= days / 2;
}

int main() {
    int m;
    scanf("%d%d", &n, &m);

    for (int i = 1; i <= n; ++i) {
        scanf("%d", &a[i]);
        sum += a[i];
    }

    events.reserve(m);
    for (int i = 0; i < m; ++i) {
        Node event;
        scanf("%d%d", &event.d, &event.b);
        events.push_back(event);
    }

    sort(events.begin(), events.end());
    events.erase(unique(events.begin(), events.end()), events.end());

    int answer = 0;
    if (sum > 0) {
        int left = 1, right = sum * 2;

        while (left <= right) {
            int middle = left + (right - left) / 2;
            if (check(middle)) {
                answer = middle;
                right = middle - 1;
            } else {
                left = middle + 1;
            }
        }
    }

    printf("%d\n", answer);
    return 0;
}

